'use strict';

// MODULES //

var tape = require( 'tape' );
var hasOwnProp = require( '@stdlib/assert/has-own-property' );
var isFunction = require( '@stdlib/assert/is-function' );
var FIFO = require( './../lib' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof FIFO, 'function', 'main export is a function' );
	t.end();
});

tape( 'attached to the prototype of the main export is a `set` method for setting one or more queue elements', function test( t ) {
	t.strictEqual( hasOwnProp( FIFO.prototype, 'set' ), true, 'has property' );
	t.strictEqual( isFunction( FIFO.prototype.set ), true, 'has method' );
	t.end();
});

tape( 'the method throws an error if invoked with a `this` context which is not a FIFO instance', function test( t ) {
	var values;
	var q;
	var i;

	q = new FIFO();
	q.push( 'foo' );

	values = [
		'5',
		5,
		NaN,
		true,
		false,
		null,
		void 0,
		{},
		[]
	];
	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[i] ), TypeError, 'throws an error when provided '+values[i] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			return q.set.call( value, 'a', 0 );
		};
	}
});

tape( 'the method throws an error if provided an index argument which is not a nonnegative integer', function test( t ) {
	var values;
	var q;
	var i;

	q = new FIFO();
	q.push( 'foo' );

	values = [
		'5',
		-5,
		3.14,
		NaN,
		true,
		false,
		null,
		void 0,
		{},
		[],
		function noop() {}
	];
	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[i] ), TypeError, 'throws an error when provided '+values[i] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			return q.set( 'x', value );
		};
	}
});

tape( 'the method throws a RangeError if provided an index argument which is out-of-bounds', function test( t ) {
	var values;
	var q;
	var i;

	q = new FIFO();
	q.push( 1 );
	q.push( 2 );

	values = [
		q.length,
		q.length + 1,
		q.length + 2
	];
	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[i] ), RangeError, 'throws an error when provided '+values[i] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			return q.set( 'x', value );
		};
	}
});

tape( 'the method sets a queue element (default index)', function test( t ) {
	var q;
	var v;

	q = new FIFO();
	q.push( 'a' );
	q.push( 'b' );

	q.set( 'z' );
	v = q.get( 0 );
	t.strictEqual( v, 'z', 'sets first element when no index provided' );
	t.end();
});

tape( 'the method sets a queue element (specified index)', function test( t ) {
	var q;
	var v;

	q = new FIFO();
	q.push( 'a' );
	q.push( 'b' );
	q.push( 'c' );

	q.set( 'x', 1 );
	v = q.get( 1 );
	t.strictEqual( v, 'x', 'sets element at index 1' );
	t.end();
});

tape( 'queue instances support numeric indexing (read)', function test( t ) {
	var q = new FIFO();
	q.push( 'a' ).push( 'b' ).push( 'c' );

	t.strictEqual( q.get( 0 ), 'a', 'get(0) matches' );
	t.strictEqual( q.get( 1 ), 'b', 'get(1) matches' );
	t.strictEqual( q.get( 2 ), 'c', 'get(2) matches' );
	t.strictEqual( q.length, 3, 'length property accessible' );
	t.end();
});

tape( 'queue instances support numeric indexing (write)', function test( t ) {
	var q = new FIFO();
	q.push( 'a' ).push( 'b' );

	q.set( 'x', 1 );
	t.strictEqual( q.get( 1 ), 'x', 'set(1) updated element' );
	t.end();
});
